{"content": "import sys
sys.path.insert(0, "src")
import numpy as np
import pandas as pd
from fleetrisk import config, pipeline, observation, model, assemble, recent, station_history

from variants10 import CFG, REF, make_observed, make_attach, by_tail_g
from variants6 import make_recent, make_station
from variants7 import make_recent_row
from base2 import run2

station_history.add = make_station("arr", "station_flights")

combos = []
for om in ("fitend_le", "all"):
    for lbl in ("ix", "xi"):
        for rec in ("snap_zero", "row"):
            combos.append((om, lbl, rec))

def obs_all(df, fit_spec, export_end, window_days):
    return pd.Series(True, index=df.index)

for om, lbl, rec in combos:
    si, ei = (True, False) if lbl == "ix" else (False, True)
    observation.attach_label = make_attach(si, ei)
    observation.observed = obs_all if om == "all" else make_observed("fitend_le")
    if rec == "snap_zero":
        recent.add = make_recent("recent", "zero", True)
    else:
        recent.add = make_recent_row("prior_zero", False)
    run2("obs=%s lbl=%s rec=%s" % (om, lbl, rec), *pipeline.build(CFG))
